    if (notifNewTitle) notifNewTitle.style.display = newItems.length > 0 ? "" : "none";
    if (notifOldTitle) notifOldTitle.style.display = oldItems.length > 0 ? "" : "none";
    if (notifList) notifList.style.display = newItems.length > 0 ? "" : "none";
